// 只显示本人实际承诺与有限步骤的已知预计；期限来自原owner而不是意向快照。
#include "plan_views.hpp"
#include "plan_codec.hpp"
#include "resident/domains/tasks/task_model.hpp"
#include "resident/domains/growth/growth_model.hpp"
#include <limits>
namespace hanmo::resident {
namespace {
// 未知值显式输出null，不能以零时刻或空安全提示冒充确定结论。
BoundaryValue number(const std::optional<Integer>& value){return value?BoundaryValue{*value}:BoundaryValue{};}
// 冷投影只输出有限引用，不携带原合同、题目或他人资产。
StableId commitment_kind(PlayerCommitmentKind kind){return kind==PlayerCommitmentKind::task?"task":"course";}
// 已结束步骤不再消耗未来时间，但后续估计仍基于当前时刻。
const PlayerPlanProjectedStep* projected(const PlayerPlanProjection& projection,const StableId& id){for(const auto& step:projection.steps)if(step.step_id==id)return &step;return nullptr;}
}
// 仅本人已接受任务和实际课程形成已知承诺，未接受邀请不算失约。
Outcome<std::vector<PlayerKnownCommitment>> known_player_commitments(const CommonStore& common,const TaskState& tasks,const TaskCatalog& catalog,const CommonCatalog& shared,const GrowthState& growth,const StableId& actor){
    if(actor!=common.state().metadata.player_actor_id||!common.actor(actor))return {false,{},common_failure("PlayerPlanActorRequired").error};
    std::vector<PlayerKnownCommitment> result;
    for(const auto& row:tasks.tasks.rows()){const auto& task=row.second;if(task.assignee!=actor||(task.status!="active"&&task.status!="ready"&&task.status!="settling"))continue;const auto* definition=resolve_task_definition(tasks,catalog,task);if(!definition)return {false,{},common_failure("UnknownOffer",task.id).error};auto* report=shared.roles.find(definition->report_role);if(!report)return {false,{},common_failure("UnknownRole",task.id).error};Integer due=task.deadline_tick;if(task.contract_id){const auto* contract=tasks.contracts.find(*task.contract_id);if(!contract||contract->frozen_terms.deadline_tick!=task.deadline_tick)return {false,{},common_failure("InvalidTaskContract",task.id).error};due=contract->frozen_terms.deadline_tick;}PlayerKnownCommitment known;known.ref={PlayerCommitmentKind::task,task.id};known.status=task.status;known.due_tick=due;known.place_id=report->place_id;known.label=definition->display_name;result.push_back(std::move(known));if(result.size()>128)return {false,{},common_failure("PlayerPlanCommitmentLimit").error};}
    for(const auto& row:growth.facts.rows()){const auto* fact=std::get_if<StudyFact>(&row.second);if(!fact||fact->actor_id!=actor||fact->phase!="started")continue;PlayerKnownCommitment known;known.ref={PlayerCommitmentKind::course,row.first};known.status="active";known.place_id=fact->terms.context.place_id;known.label=fact->terms.skill_id;const auto* action=common.action(row.first);bool paused=fact->pauses&&!fact->pauses->empty()&&fact->pauses->back().end_tick<0;if(paused)known.status="paused";if(action&&!paused&&action->remaining_ticks>=0){if(action->remaining_ticks>std::numeric_limits<Integer>::max()-common.tick())return {false,{},common_failure("PlayerPlanEstimateOverflow").error};known.estimated_completion_tick=common.tick()+action->remaining_ticks;}result.push_back(std::move(known));if(result.size()>128)return {false,{},common_failure("PlayerPlanCommitmentLimit").error};}
    return {true,std::move(result),{}};
}
// 有限顺序估计保留未知传播，使用完成边界提示期限风险。
Outcome<PlayerPlanProjection> project_player_plan(const PlayerPlanState& state,Integer tick,const std::vector<PlayerKnownCommitment>& commitments,const PlayerPlanEstimateRead& estimate){
    auto checked=validate_player_plan_shape(state);if(!checked.ok)return {false,{},checked.error};if(tick<0||commitments.size()>128)return {false,{},common_failure("InvalidPlayerPlanProjection").error};PlayerPlanProjection result;result.commitments=commitments;if(!state.current)return {true,std::move(result),{}};std::optional<Integer> cursor=tick;
    for(const auto& step:state.current->steps){PlayerPlanProjectedStep row;row.step_id=step.id;if(step.completed_tick){row.start_tick=step.started_tick;row.completion_tick=step.completed_tick;row.estimate_source="actual_result";if(step.phase==PlayerPlanStepPhase::blocked){cursor.reset();row.unknown_reason=step.stop_reason;}result.steps.push_back(std::move(row));continue;}row.start_tick=cursor;auto known=estimate?estimate(step):PlayerPlanEstimate{{},{},"DurationUnknown"};row.estimate_source=known.source;row.unknown_reason=known.unknown_reason;if(known.remaining_ticks&&*known.remaining_ticks<0)return {false,{},common_failure("InvalidPlayerPlanEstimate",step.id).error};if(cursor&&known.remaining_ticks){if(*known.remaining_ticks>std::numeric_limits<Integer>::max()-*cursor)return {false,{},common_failure("PlayerPlanEstimateOverflow",step.id).error};row.completion_tick=*cursor+*known.remaining_ticks;cursor=row.completion_tick;}else{cursor.reset();if(row.unknown_reason.empty())row.unknown_reason=row.start_tick?"DurationUnknown":"PreviousStepUnknown";}result.steps.push_back(std::move(row));}
    // 每个承诺只给一个最早的已知冲突或未知提示，办理提示本身不能算已履约。
    for(const auto& commitment:commitments){if(!commitment.due_tick)continue;if(*commitment.due_tick<0)return {false,{},common_failure("InvalidPlayerPlanDeadline").error};PlayerPlanConflict conflict;conflict.commitment=commitment.ref;conflict.due_tick=*commitment.due_tick;conflict.unknown=true;
        for(const auto& step:state.current->steps){if(step.completed_tick)continue;const auto* row=projected(result,step.id);if(!row)continue;const auto* reminder=std::get_if<PlayerPlanTaskReminder>(&step.data);const bool target=reminder&&commitment.ref.kind==PlayerCommitmentKind::task&&reminder->task_id==commitment.ref.source_id;if(target){conflict.step_id=step.id;conflict.estimated_completion_tick=row->completion_tick;conflict.known_conflict=row->completion_tick&&*row->completion_tick>conflict.due_tick;conflict.unknown=!row->completion_tick;break;}if(row->completion_tick&&*row->completion_tick>conflict.due_tick){conflict.step_id=step.id;conflict.estimated_completion_tick=row->completion_tick;conflict.known_conflict=true;conflict.unknown=false;break;}}
        result.conflicts.push_back(std::move(conflict));
    }
    return {true,std::move(result),{}};
}
// 页面只输出有限已知字段和不确定性，不泄漏完整领域状态。
BoundaryValue encode_player_plan_view(const PlayerPlanState& state,const PlayerPlanProjection& projection){using namespace boundary;auto result=obj({{"enabled",BoundaryValue{true}},{"plan_id",BoundaryValue{state.current?state.current->id:StableId{}}},{"actor_id",BoundaryValue{state.current?state.current->actor_id:StableId{}}},{"stop_reason",BoundaryValue{state.current?state.current->stop_reason:StableId{}}},{"estimate_basis",BoundaryValue{StableId{"current_known_conditions"}}},{"guaranteed",BoundaryValue{false}}});BoundaryValue::Array steps,commitments,conflicts;
    if(state.current){auto encoded=encode_player_plan_state(state);steps=*encoded.find("current")->find("steps")->as<BoundaryValue::Array>();for(auto& value:steps){auto& fields=*value.as<BoundaryValue::Dict>();const auto id=get_string(value,"step_id","view");const auto* row=projected(projection,id);fields.emplace_back("estimated_start_tick",row?number(row->start_tick):BoundaryValue{});fields.emplace_back("estimated_completion_tick",row?number(row->completion_tick):BoundaryValue{});fields.emplace_back("estimate_source",BoundaryValue{row?row->estimate_source:StableId{}});fields.emplace_back("unknown_reason",BoundaryValue{row?row->unknown_reason:StableId{"DurationUnknown"}});const auto source=field(value,"source","view");fields.emplace_back("source_id",field(source,"source_id","view"));fields.emplace_back("observed_tick",field(source,"observed_tick","view"));}
        if(state.current->budget)result.as<BoundaryValue::Dict>()->emplace_back("budget",*encoded.find("current")->find("budget"));}
    for(const auto& known:projection.commitments)commitments.push_back(obj({{"kind",BoundaryValue{commitment_kind(known.ref.kind)}},{"source_id",BoundaryValue{known.ref.source_id}},{"status",BoundaryValue{known.status}},{"due_tick",number(known.due_tick)},{"required_boundary",BoundaryValue{known.required_boundary}},{"place_id",BoundaryValue{known.place_id}},{"label",BoundaryValue{known.label}},{"estimated_completion_tick",number(known.estimated_completion_tick)}}));
    for(const auto& conflict:projection.conflicts)conflicts.push_back(obj({{"step_id",BoundaryValue{conflict.step_id}},{"commitment_kind",BoundaryValue{commitment_kind(conflict.commitment.kind)}},{"commitment_id",BoundaryValue{conflict.commitment.source_id}},{"due_tick",BoundaryValue{conflict.due_tick}},{"estimated_completion_tick",number(conflict.estimated_completion_tick)},{"known_conflict",BoundaryValue{conflict.known_conflict}},{"unknown",BoundaryValue{conflict.unknown}}}));
    auto& rows=*result.as<BoundaryValue::Dict>();rows.emplace_back("steps",BoundaryValue{std::move(steps)});rows.emplace_back("commitments",BoundaryValue{std::move(commitments)});rows.emplace_back("conflicts",BoundaryValue{std::move(conflicts)});return result;
}
} // 页面不是原行动报价，不保证未来可用或授权；开始仍由原领域当场审核。
